widget.solution:
def generate(gens, op, e):
    H = {e} | set(gens)
    frontier = list(H)
    while frontier:
        x = frontier.pop()
        for g in gens:
            y = op(x, g)
            if y not in H:
                H.add(y)
                frontier.append(y)
    return sorted(H)
